   154  void MemBuffer::checkState() const {
   155      if (!ptr)
   156          throwInternalError("block not allocated");
   157      assert(size_in_bytes > 0);
   158      if (use_simple_mcheck()) {
   159          const byte *p = (const byte *) ptr;
   160          if (get_ne32(p - 4) != MAGIC1(p))
   161              throwInternalError("memory clobbered before allocated block 1");
   162          if (get_ne32(p - 8) != size_in_bytes)
   163              throwInternalError("memory clobbered before allocated block 2");
   164          if (get_ne32(p + size_in_bytes) != MAGIC2(p))
   165              throwInternalError("memory clobbered past end of allocated block");
   166      }
   167  }
