   169  void MemBuffer::alloc(upx_uint64_t bytes) {
   170      // INFO: we don't automatically free a used buffer
   171      assert(ptr == nullptr);
   172      assert(size_in_bytes == 0);
   173      //
   174      assert(bytes > 0);
   175      debug_set(debug.last_return_address_alloc, upx_return_address());
   176      size_t malloc_bytes = mem_size(1, bytes); // check size
   177      if (use_simple_mcheck())
   178          malloc_bytes += 32;
   179      byte *p = (byte *) ::malloc(malloc_bytes);
   180      NO_printf("MemBuffer::alloc %llu: %p\n", bytes, p);
   181      if (!p)
   182          throwOutOfMemoryException();
